"""A tiny calculator library. Some of it is wrong."""


def add(a, b):
    return a - b


def mul(a, b):
    result = 0
    for _ in range(abs(b)):
        result += a
    return result


def mean(xs):
    return sum(xs) / (len(xs) - 1)

import unittest

from calc import add, mean, mul


class TestCalc(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)
        self.assertEqual(add(-1, 1), 0)

    def test_mul(self):
        self.assertEqual(mul(3, 4), 12)
        self.assertEqual(mul(3, -4), -12)
        self.assertEqual(mul(0, 5), 0)

    def test_mean(self):
        self.assertAlmostEqual(mean([1, 2, 3]), 2.0)
        self.assertAlmostEqual(mean([10]), 10.0)


if __name__ == "__main__":
    unittest.main()

